    const struct RamEntry final_ram[] = {
        {.addr=0x2cf8, .value=0x85}, {.addr=0x2cf9, .value=0x40}, {.addr=0x2cfa, .value=0x68},
        {.addr=0x6840, .value=0x44},
    };
    const struct BusEvent events[] = {
        {.addr=0x2cf8, .value=0x85, .type=IO_READ},
        {.addr=0x2cf9, .value=0x40, .type=IO_READ},
        {.addr=0x2cfa, .value=0x68, .type=IO_READ},
        {.addr=0x6840, .value=0x44, .type=IO_READ},
    };
